begin; create or replace function public.pending_questions_all() returns table (other uuid, pending int) language sql stable security definer set search_path = public as $fn$ with me as (select auth.uid() as id), friends as (select case when f.user_a = me.id then f.user_b else f.user_a end as other from public.friendships f, me where f.status = 'accepted' and me.id in (f.user_a, f.user_b)) select fr.other, (select count(*) from public.pair_questions q, me where q.user_a = least(me.id, fr.other) and q.user_b = greatest(me.id, fr.other) and q.asker = fr.other and q.answer is null)::int as pending from friends fr; $fn$; revoke all on function public.pending_questions_all() from public, anon; grant execute on function public.pending_questions_all() to authenticated; notify pgrst, 'reload schema'; commit;
